mapper.select:
SELECT DISTINCT v.shop_id
FROM tb_voucher v
INNER JOIN tb_seckill_voucher sv ON v.id = sv.voucher_id
WHERE v.status = 1
  AND v.type = 1
  AND sv.end_time > #{now}
  AND sv.begin_time <= #{startsBefore}
  AND sv.begin_time < sv.end_time
ORDER BY v.shop_id
LIMIT #{limit}

SELECT v.`id`, v.`shop_id`, v.`title`, v.`sub_title`, v.`rules`, v.`pay_value`, v.`actual_value`, v.`type`, sv.`stock` , sv.begin_time , sv.end_time FROM tb_voucher v LEFT JOIN tb_seckill_voucher sv ON v.id = sv.voucher_id WHERE v.status = 1 AND v.id IN
#{id}
ORDER BY v.id
